import{_ as r,l as t,o as e,c as d,v as o,p as i,x as n,d as s,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"Reed–Solomon","description":"","frontmatter":{"title":"Reed–Solomon","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reed-solomon.md","filePath":"cs/reed-solomon.md","lastUpdated":1789023840000}'),h={name:"cs/reed-solomon.md"};function c(S,a,_,k,u,B){const l=t("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="reed–solomon" tabindex="-1">Reed–Solomon <a class="header-anchor" href="#reed–solomon" aria-label="Permalink to &quot;Reed–Solomon&quot;">​</a></h1><div class="epigraph"><p>把信息当成多项式系数，在有限域的 $n$ 个点上求值；任意 $k$ 个点都能重建，于是可纠 $n-k$ 个符号级擦除，或约一半替换错误。</p><footer>—— 据 Reed and Solomon, 1960；MacWilliams and Sloane 整理</footer></div><p>上一课<a href="/cs/hamming-code">汉明码</a> 是二元、纠 1 比特。缺口是<strong>符号级</strong>：磁盘扇区、QR、光盘上的突发错误。Reed–Solomon（RS）在 \\(\\mathbb{F}_q\\) 上，\\(q\\gt n\\)，码字是次数 \\(\\lt k\\) 的多项式的求值向量。\\(d_{\\min}=n-k+1\\)（Singleton 达到，MDS）。本课要求值图像；有限域构造在数论单元。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信息 \\(m(x)=m_0+\\cdots+m_{k-1}x^{k-1}\\)。码字 \\((m(\\alpha_1),\\ldots,m(\\alpha_n))\\)。擦除 \\(e\\) 个位置：剩 \\(n-e\\ge k\\) 个点，插值唯一。替换错误 \\(t\\)：Berlekamp–Welch / 关键方程，可纠 \\(t\\le\\lfloor(n-k)/2\\rfloor\\)。突发：二元突发变成少数符号错，RS 比 Hamming 合适。</p><p>不要在本课展开 \\(\\mathrm{GF}(2^8)\\) 的不可约多项式——只假设能算加减乘除。</p><h3 id="距离是符号汉明距离" tabindex="-1">距离是符号汉明距离 <a class="header-anchor" href="#距离是符号汉明距离" aria-label="Permalink to &quot;距离是符号汉明距离&quot;">​</a></h3><p><a href="/cs/hamming-distance">汉明距离</a> 课已声明 RS 换字母表。一个符号错可以是 8 比特全翻，仍只计距离 1。</p><p><span class="marginnote">Reed–Solomon 1960。Peterson、Berlekamp 译码。Justesen、Guruswami–Sudan 列表译码点名。存储阵列、QR 是应用，不是定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用小域手写 \\(k=2,n=4\\) 求值。对照重复码、Hamming：MDS 在给定 \\(n,k\\) 下 \\(d\\) 最大。指出：编码是线性的（Vandermonde）。译码比伴随式定位重，本课只给「插值 / 关键方程」名字。</p>',11)),(e(),i(p,null,{default:n(()=>[m(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSG%5B%22k%20%E4%B8%AA%E7%B3%BB%E6%95%B0%22%5D%20--%3E%20POLY%5B%22%E6%AC%A1%E6%95%B0%20%EF%BC%9C%20k%20%E7%9A%84%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20POLY%20--%3E%20EVAL%5B%22n%20%E4%B8%AA%E7%82%B9%E6%B1%82%E5%80%BC%22%5D%0A%20%20EVAL%20--%3E%20MDS%5B%22d%20%3D%20n-k%2B1%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>容量：RS 不随 \\(n\\to\\infty\\) 在 BSC 上自动达容量（字母表也在涨）。它是代数码的代表，后课 LDPC 才是近容量的稀疏随机码。RS 常作外码，与内码级联。</p><p>多项式观点与主干 CRC 同族：CRC 检错，RS 纠错并给距离公式。</p><p>BCH 码把 RS 看成设计距离的子域子码；二进制 BCH 纠少量比特时比 Hamming 更灵活。Guruswami–Sudan 列表译码可超过半距离，代价是列表。级联：外 RS 去突发，内卷积或 LDPC 去随机，是深空通信的经典分层，后课内码。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Berlekamp–Massey 全文，不引入 BCH 的设计距离。有限域下一单元才系统讲。后课默认：符号 MDS 码即 RS 直觉。下一课卷积与 Viterbi。</p><p>MDS 在给定 \\(n,k\\) 下距离最大，字母表必须够大。插值重建擦除；替换错误要关键方程。有限域算术本单元只假设能做，构造在数论课。</p><p>上一课留下的缺口在本课收口；「Reed–Solomon」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RS = 多项式求值；MDS，\\(d=n-k+1\\)。</li><li>纠擦除到 \\(n-k\\)，纠替换到 \\(\\lfloor(n-k)/2\\rfloor\\)。</li><li>字母表是有限域符号，不是比特汉明。</li><li>出处：Reed and Solomon, 1960；MacWilliams and Sloane。</li></ul>',10))])}const A=r(h,[["render",c]]);export{R as __pageData,A as default};
